(1) 1 = ind = {∅, 𝑋}

(2) 2 = {∅, {𝑎}, 𝑋}

(3) 3 = {∅, {𝑎, 𝑏}, 𝑋}

(4) 4 = {∅, {𝑎}, {𝑎, 𝑏}, 𝑋}

(5) 5 = {∅, {𝑎, 𝑏}, {𝑏}, {𝑏, 𝑐}, 𝑋}

(6) 6 = disc = (𝑋) = {∅, {𝑎}, {𝑎, 𝑏}, {𝑎, 𝑐}, {𝑏}, {𝑏, 𝑐}, {𝑐}, 𝑋}

